{"source":"import json
import sys
from datetime import datetime, timezone

def parse_iso8601(dt_str):
    """Parse an offset-aware ISO8601 string to a datetime with timezone."""
    if dt_str is None:
        return None
    # Handle 'Z' suffix by replacing with '+00:00'
    if dt_str.endswith('Z'):
        dt_str = dt_str[:-1] + '+00:00'
    # Try parsing with timezone info
    try:
        # Python 3.12 handles ISO format with offsets well
        return datetime.fromisoformat(dt_str)
    except ValueError:
        return None

def is_naive(dt):
    """Check if a datetime is naive (no timezone info)."""
    return dt.tzinfo is None

def format_utc(dt):
    """Format a datetime as YYYY-MM-DDTHH:MM:SSZ in UTC."""
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc)
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

def main():
    input_file = sys.argv[1]
    with open(input_file, 'r') as f:
        data = json.load(f)

    as_of_str = data['as_of']
    as_of = parse_iso8601(as_of_str)
    if as_of is None:
        print(json.dumps([]))
        return

    reminders = data.get('reminders', [])
    pending = []

    for r in reminders:
        # Skip completed reminders
        if r.get('completed', False):
            continue

        due_str = r.get('due')
        # Skip missing/null due values
        if due_str is None:
            continue

        due_dt = parse_iso8601(due_str)
        # Skip naive datetimes (no timezone info)
        if due_dt is None or is_naive(due_dt):
            continue

        # Check if due AT OR BEFORE as_of
        if due_dt <= as_of:
            pending.append({
                'id': r['id'],
                'title': r['title'],
                'due_utc': format_utc(due_dt),
                'due_dt': due_dt
            })

    # Sort by actual due instant then id
    pending.sort(key=lambda x: (x['due_dt'], x['id']))

    # Output only the required fields
    result = [{'id': x['id'], 'title': x['title'], 'due_utc': x['due_utc']} for x in pending]
    print(json.dumps(result))

if __name__ == '__main__':
    main()"}

